create table public.teacher_query_defaults(school_id uuid not null,teacher_id uuid primary key,hours int not null check(hours between 1 and 336),revision int not null default 1,foreign key(school_id,teacher_id)references public.memberships(school_id,id));
alter table public.teacher_query_defaults enable row level security;create policy read_scope on public.teacher_query_defaults for select to authenticated using(school_id=private.school()and private.role()is not null and not private.active_attempt());grant select on public.teacher_query_defaults to authenticated;
create function public.set_query_fallback(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();begin perform private.require_access(s,true);if private.role()<>'teacher'then raise exception 'FORBIDDEN'using errcode='42501';end if;insert into public.teacher_query_defaults values(s,auth.uid(),(p->>'hours')::int,1)on conflict(teacher_id)do update set hours=excluded.hours,revision=teacher_query_defaults.revision+1;perform private.audit(s,'query.fallback',auth.uid());end$$;
revoke execute on function public.set_query_fallback(jsonb)from public,anon,authenticated;grant execute on function public.set_query_fallback(jsonb)to authenticated;
